import{_ as a,C as i,o as r,c as s,j as e,a as n,E as h,a2 as l}from"./chunks/framework.BxGh02fV.js";const b=JSON.parse('{"title":"Git","description":"","frontmatter":{"title":"Git"},"headers":[],"relativePath":"en/guide/git.md","filePath":"en/guide/git.md"}'),c={name:"en/guide/git.md"};function d(m,t,u,g,f,p){const o=i("Capture");return r(),s("div",null,[t[0]||(t[0]=e("h1",{id:"git",tabindex:"-1"},[n("Git "),e("a",{class:"header-anchor",href:"#git","aria-label":'Permalink to "Git"'},"​")],-1)),t[1]||(t[1]=e("p",null,"This screen shows the local git state of the workspace and lets you commit Effortless metadata without leaving the app. You come here to see what has changed, or to record the tracking state in the history.",-1)),h(o,{name:"git",alt:"The Git screen: branch, modified files and the git identity of each repository"}),t[2]||(t[2]=l('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>Under the <strong>Git (local)</strong> title, four cards follow one another from top to bottom. The screenshot only shows the beginning; scroll down to see the rest.</p><ol><li><strong>Branch</strong> and <strong>Modified files</strong>: the current branch, then the list of modified files. If the tree is clean, the screen shows &quot;Working directory clean.&quot; If the folder is not a repository, it shows &quot;This directory is not a git repository.&quot;</li><li><strong>Git identity</strong>: your profile&#39;s name and email, then each repository (the project, and each module with its own repository) with the identity that signs its commits and its scope (<code>local</code> or <code>global</code>). A green check: the repository signs with your profile; a red cross: it differs.</li><li><strong>Auto-commit metadata</strong>, <strong>Commit message</strong> and the <strong>Commit the metadata</strong> button.</li><li><strong>Recent commits</strong>: a table (<strong>Hash</strong>, <strong>Subject</strong>, <strong>Date</strong>) of the last ten commits, and a <strong>Refresh</strong> button.</li></ol><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="sign-with-the-profile-identity" tabindex="-1">Sign with the profile identity <a class="header-anchor" href="#sign-with-the-profile-identity" aria-label="Permalink to &quot;Sign with the profile identity&quot;">​</a></h3><p>The commits Effortless launches already carry your name and email. The ones you make by hand follow the repository&#39;s git config: if it holds another identity, your commits are not credited to you. Such a repository also appears in <strong>What is waiting for you</strong> on the dashboard.</p><ol><li>Click <strong>Set the profile identity…</strong>. The button only appears when a repository differs.</li><li>Read what will be written, then click <strong>Set</strong>. Your name and email go into the <strong>local</strong> git config of each repository that differs; your global config is never touched. <strong>Cancel</strong> changes nothing.</li></ol><p>The card also says whether the profile email is linked to your GitHub account: &quot;Email linked to the GitHub account …&quot;, &quot;Email missing from the GitHub account …&quot; (your commits will not be credited to you), or &quot;Email not checked with GitHub&quot; with its reason. For the check to happen, <code>gh</code> must be installed and signed in with the <code>user</code> scope: <code>gh auth refresh -h github.com -s user</code>.</p><h3 id="turn-on-auto-commit" tabindex="-1">Turn on auto-commit <a class="header-anchor" href="#turn-on-auto-commit" aria-label="Permalink to &quot;Turn on auto-commit&quot;">​</a></h3><p>Tick <strong>Auto-commit metadata</strong>. Effortless then automatically commits <code>.effortless</code> and <code>blueprints</code> after every action taken in the app (ADR, BQO, task, phase). It never commits code. Each auto-commit is announced by a notification (&quot;Auto-commit …&quot; followed by the hash), or says why it was skipped.</p><p>The box is not remembered: it goes back to unticked when you return to the picker or the preferences, and at every launch.</p><h3 id="commit-the-metadata-by-hand" tabindex="-1">Commit the metadata by hand <a class="header-anchor" href="#commit-the-metadata-by-hand" aria-label="Permalink to &quot;Commit the metadata by hand&quot;">​</a></h3><ol><li>Type a <strong>Commit message</strong>. If you leave it empty, Effortless uses <code>chore(effortless): update metadata</code>.</li><li>Click <strong>Commit the metadata</strong>.</li></ol><p>The screen shows &quot;Commit created:&quot; followed by the hash. The button is disabled if the folder is not a git repository.</p><h3 id="reread-the-history" tabindex="-1">Reread the history <a class="header-anchor" href="#reread-the-history" aria-label="Permalink to &quot;Reread the history&quot;">​</a></h3><p>Click <strong>Refresh</strong> to read the state and the commit list again.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>This button only commits metadata. You still commit your code files yourself; the hook from the <a href="/Effortless/en/guide/drift.html">Drift</a> screen then checks that a task is in progress.</li><li>A branch shown as &quot;(none)&quot; means the repository has no commit yet or is not attached to a branch. With no commit at all, the table shows &quot;No commit in the history.&quot;</li></ul>',18))])}const w=a(c,[["render",d]]);export{b as __pageData,w as default};
